const $ = id => document.getElementById(id);
const canvas = $('poster'), ctx = canvas.getContext('2d');
const slot = {x:52,y:600,w:430,h:424,r:28};
const state = {template:null,original:null,cutout:null,active:null,file:null,zoom:1,x:0,y:0,removed:false,busy:false,generation:0,urls:[]};
const controls = ['zoom','horizontal','vertical','reset'];
function status(message,type=''){ $('status').textContent=message; $('status').className='status '+type; }
function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('This image could not be opened. Please use a JPG, PNG or WEBP photo.'));im.src=src;});}
function useUrl(blob){const url=URL.createObjectURL(blob);state.urls.push(url);return url;}
function updateButtons(){for(const id of controls)$(id).disabled=!state.active||state.busy; $('removeBg').disabled=!state.active||state.busy; $('download').disabled=!state.active||!state.template||state.busy;$('photoInput').disabled=state.busy;$('keepBg').disabled=state.busy;$('replace').disabled=state.busy;}
function resetPosition(){state.zoom=1;state.x=0;state.y=0;$('zoom').value=100;$('horizontal').value=0;$('vertical').value=0;$('zoomValue').value='100%';render();}
function render(){if(!state.template)return;ctx.clearRect(0,0,1164,1280);ctx.drawImage(state.template,0,0,1164,1280);
 // Replace only the countdown footprint. The church portraits and all other artwork remain source pixels.
 ctx.fillStyle='#fff';ctx.beginPath();ctx.moveTo(0,550);ctx.lineTo(145,550);ctx.lineTo(145,603);ctx.lineTo(536,603);ctx.lineTo(536,1062);ctx.lineTo(420,1062);ctx.lineTo(420,1095);ctx.lineTo(0,1095);ctx.closePath();ctx.fill();ctx.fillRect(155,580,43,25);ctx.fillRect(343,577,45,28);
 const photoBackground='#ffffff';
 ctx.save();ctx.shadowColor='#133ba62b';ctx.shadowBlur=20;ctx.shadowOffsetY=8;rounded(slot.x,slot.y,slot.w,slot.h,slot.r);ctx.fillStyle=photoBackground;ctx.fill();ctx.restore();
 ctx.save();rounded(slot.x,slot.y,slot.w,slot.h,slot.r);ctx.clip();
 if(state.active){const im=state.active;const scale=Math.max(slot.w/im.naturalWidth,slot.h/im.naturalHeight)*state.zoom;const w=im.naturalWidth*scale,h=im.naturalHeight*scale;const maxX=Math.max(0,(w-slot.w)/2),maxY=Math.max(0,(h-slot.h)/2);const x=Math.max(-maxX,Math.min(maxX,state.x)),y=Math.max(-maxY,Math.min(maxY,state.y));ctx.drawImage(im,slot.x+(slot.w-w)/2+x,slot.y+(slot.h-h)/2+y,w,h);
 }else{ctx.fillStyle='#c2d2f3';ctx.beginPath();ctx.arc(267,757,57,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(267,923,114,100,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#234c9f';ctx.textAlign='center';ctx.font='600 23px Arial';ctx.fillText('YOUR PHOTO HERE',267,978);}
 ctx.restore();rounded(slot.x,slot.y,slot.w,slot.h,slot.r);ctx.strokeStyle='#0c51dc';ctx.lineWidth=6;ctx.stroke();
 ctx.fillStyle='#ff1824';rounded(32,995,470,64,9);ctx.fill();ctx.textAlign='center';ctx.fillStyle='white';ctx.font='900 32px Arial';ctx.fillText('I WILL BE ATTENDING',267,1037);
 const name=$('name').value.trim();if(name){ctx.font='700 24px Arial';while(ctx.measureText(name).width>390){const size=parseInt(ctx.font.match(/\d+/)[0]);if(size<=12)break;ctx.font=`700 ${size-1}px Arial`;}ctx.fillStyle='#05174b';ctx.fillText(name,245,1085);}
}
async function choosePhoto(file){if(state.busy||!file)return;if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type)){status('Please choose a JPG, PNG, WEBP or AVIF image.','error');return;}if(file.size>20*1024*1024){status('This photo is larger than 20 MB. Choose a smaller photo.','error');return;}const version=++state.generation;try{status('Opening your photo…');let im=await loadImage(useUrl(file));if(version!==state.generation)return;
 // Resize large camera images before processing to avoid exhausting phone memory.
 const resize=document.createElement('canvas');const factor=Math.min(1,2000/Math.max(im.naturalWidth,im.naturalHeight));resize.width=Math.round(im.naturalWidth*factor);resize.height=Math.round(im.naturalHeight*factor);resize.getContext('2d').drawImage(im,0,0,resize.width,resize.height);const blob=await new Promise(resolve=>resize.toBlob(resolve,'image/png'));if(!blob)throw new Error('Could not prepare this photo. Try another image.');im=await loadImage(useUrl(blob));
 if(version!==state.generation)return;state.original=im;state.active=im;state.file=blob;state.cutout=null;state.removed=false;setChoice(false);resetPosition();updateButtons();canvas.classList.add('has-photo');$('uploadTitle').textContent='Your photo is ready';$('uploadHint').textContent='Adjust it below, or choose another';$('uploadIcon').textContent='✓';$('replace').hidden=false;status('Looking good! Drag the photo or use the sliders, then download.','success');
 }catch(e){status(e.message,'error');}}
function setChoice(removed){$('keepBg').classList.toggle('active',!removed);$('removeBg').classList.toggle('active',removed);$('keepBg').setAttribute('aria-pressed',String(!removed));$('removeBg').setAttribute('aria-pressed',String(removed));}
$('photoInput').addEventListener('change',e=>choosePhoto(e.target.files[0]));$('replace').onclick=()=>$('photoInput').click();$('dropZone').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('photoInput').click();}});
for(const event of ['dragenter','dragover'])$('dropZone').addEventListener(event,e=>{e.preventDefault();$('dropZone').classList.add('dragover');});for(const event of ['dragleave','drop'])$('dropZone').addEventListener(event,e=>{e.preventDefault();$('dropZone').classList.remove('dragover');});$('dropZone').addEventListener('drop',e=>choosePhoto(e.dataTransfer.files[0]));
$('name').addEventListener('input',render);for(const id of ['zoom','horizontal','vertical'])$(id).addEventListener('input',()=>{state.zoom=+$('zoom').value/100;state.x=+$('horizontal').value;state.y=+$('vertical').value;$('zoomValue').value=$('zoom').value+'%';render();});$('reset').onclick=resetPosition;
$('keepBg').onclick=()=>{if(state.busy)return;state.active=state.original;state.removed=false;setChoice(false);resetPosition();updateButtons();if(state.active)status('Original background restored.','success');};
$('removeBg').onclick=async()=>{if(!state.original||state.busy)return;if(state.cutout){state.active=state.cutout;state.removed=true;setChoice(true);resetPosition();return;}state.busy=true;updateButtons();const button=$('removeBg');button.textContent='Preparing…';status('Loading background removal. The first use needs a model download; please keep this page open.');const version=state.generation;try{
 const {removeBackground}=await import('https://esm.sh/@imgly/background-removal@1.7.0');
 const blob=await removeBackground(state.file,{model:'isnet_quint8',device:'cpu',proxyToWorker:false,output:{format:'image/png',quality:1},progress:(key,current,total)=>{if(total>0)status(`Preparing background removal… ${Math.min(100,Math.round(current/total*100))}%`);}});
 if(version!==state.generation)return;state.cutout=await loadImage(useUrl(blob));state.active=state.cutout;state.removed=true;setChoice(true);resetPosition();status('Background removed. Adjust the photo if needed, then download.','success');
 }catch(e){console.error('Background removal failed:',e);status('Background removal could not finish. Check your connection and try again, or keep your original background.','error');}finally{state.busy=false;button.innerHTML='<span>✧</span> Remove background';updateButtons();}};
let drag=null;canvas.addEventListener('pointerdown',e=>{if(!state.active||state.busy)return;const r=canvas.getBoundingClientRect();const x=(e.clientX-r.left)*1164/r.width,y=(e.clientY-r.top)*1280/r.height;if(x<slot.x||x>slot.x+slot.w||y<slot.y||y>slot.y+slot.h)return;drag={x:e.clientX,y:e.clientY,offsetX:state.x,offsetY:state.y,ratio:1164/r.width};canvas.setPointerCapture(e.pointerId);e.preventDefault();});canvas.addEventListener('pointermove',e=>{if(!drag)return;state.x=Math.max(-160,Math.min(160,drag.offsetX+(e.clientX-drag.x)*drag.ratio));state.y=Math.max(-160,Math.min(160,drag.offsetY+(e.clientY-drag.y)*drag.ratio));$('horizontal').value=state.x;$('vertical').value=state.y;render();});for(const e of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(e,()=>drag=null);
function exportBlob(){render();return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Could not save the flyer. Please try again.')),'image/png'));}
$('download').onclick=async()=>{if(!state.active||state.busy)return;try{const blob=await exportBlob();const a=document.createElement('a');a.href=useUrl(blob);const name=$('name').value.trim().replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'');a.download=`MZYS-Youth-Week-2026${name?'-'+name:''}.png`;document.body.append(a);a.click();a.remove();status('Your flyer is ready! Check your downloads, then share the invitation.','success');if(navigator.share&&navigator.canShare&&navigator.canShare({files:[new File([blob],'flyer.png',{type:'image/png'})]}))$('share').hidden=false;}catch(e){status(e.message,'error');}};
$('share').onclick=async()=>{try{const blob=await exportBlob();const file=new File([blob],'MZYS-Youth-Week-2026.png',{type:'image/png'});await navigator.share({files:[file],title:'I’ll be at MZYS Youth Week!',text:'Join us for MZYS Youth Week, 9–15 November 2026. Unshakable Foundation — 1 Corinthians 3:11.'});}catch(e){if(e.name!=='AbortError')status('Sharing is unavailable here. Download your flyer and share it from your gallery.','error');}};
window.addEventListener('pagehide',()=>state.urls.forEach(url=>URL.revokeObjectURL(url)));
try{state.template=await loadImage('assets/youth-week-original.jpg');render();$('loading').hidden=true;}catch(e){$('loading').textContent='The flyer could not load. Please refresh the page.';status('Please refresh to load the flyer design.','error');}
